85	TEST_F(XdsOverrideHostTest, DelegatesToChild) {
86	  ExpectStartupWithRoundRobin(
87	      {"ipv4:127.0.0.1:441", "ipv4:127.0.0.1:442", "ipv4:127.0.0.1:443"});
88	}
89	
90	TEST_F(XdsOverrideHostTest, NoConfigReportsError) {
91	  EXPECT_EQ(
92	      ApplyUpdate(BuildUpdate({"ipv4:127.0.0.1:441", "ipv4:127.0.0.1:442"}),
93	                  policy_.get()),
94	      absl::InvalidArgumentError("Missing policy config"));
95	}
