119	  class SubchannelWrapper : public DelegatingSubchannel {
120	   public:
121	    SubchannelWrapper(RefCountedPtr<SubchannelState> subchannel_state,
122	                      RefCountedPtr<SubchannelInterface> subchannel)
123	        : DelegatingSubchannel(std::move(subchannel)),
124	          subchannel_state_(std::move(subchannel_state)) {
125	      if (subchannel_state_ != nullptr) {
126	        subchannel_state_->AddSubchannel(this);
127	        if (subchannel_state_->ejection_time().has_value()) {
128	          ejected_ = true;
129	        }
130	      }
131	    }
132	
133	    ~SubchannelWrapper() override {
134	      if (subchannel_state_ != nullptr) {
135	        subchannel_state_->RemoveSubchannel(this);
136	      }
137	    }
